---Return true when the host exposes a feature such as `fs.read_file@1`.
---@param feature string `module.feature@major` query.
---@return boolean Boolean result.
function leviathan.has(feature) end

---Log a message via the host.
---@param message string Message to log to host stderr.
function leviathan.log(message) end

---Defer a callback to the next tick (top-level alias of `leviathan.api.schedule`).
---@param callback fun() Function invoked on the next tick.
function leviathan.schedule(callback) end

---Return the full host API table.
---@return table Host API table.
function leviathan.api.describe() end

---Run a Lua callback on the next plugin host tick.
---@param callback fun() Callback to enqueue.
function leviathan.api.schedule(callback) end

---Run a Lua callback after a host-side millisecond delay.
---@param ms integer Delay in milliseconds.
---@param callback fun() Callback to enqueue.
function leviathan.api.defer_fn(ms, callback) end

---Register a typed user command in the host registry.
---@param name string Command identifier; unique per plugin.
---@param spec LeviathanCommandSpec Command spec including title, args, run.
function leviathan.command.create(name, spec) end

---Invoke a registered command by name through the host dispatcher.
---@param name string Command name to invoke.
---@param args table|nil Argument table; validated against the command's arg schema.
---@return boolean True when dispatch succeeded; false on validation/capability/run failure.
function leviathan.command.invoke(name, args) end

---List every registered command.
---@return LeviathanCommandSummary[] Array of command summaries.
function leviathan.command.list() end

---Set the active keymap leader sequence used to expand `<leader>` bindings.
---@param leader string Vim-style key sequence used as leader, e.g. `<Space>` or `,`.
function leviathan.keymap.set_leader(leader) end

---Bind a key chord to a registered command in a context.
---@param context string Activation context (`global`, `repository`, `repository.graph`, `tab_bar`, etc.).
---@param key string Vim-style key sequence (e.g. `gl`, `<C-r>`, `<leader>gh`).
---@param command string Command name resolved by the host command registry at dispatch time.
---@param opts LeviathanKeymapOpts Keymap options (description, args).
function leviathan.keymap.set(context, key, command, opts) end

---Remove a previously-registered keymap owned by the calling plugin generation.
---@param context string Activation context the keymap was bound under.
---@param key string Vim-style key sequence.
function leviathan.keymap.del(context, key) end

---List every registered keymap (built-in, user, plugin) including conflict losers.
---@return LeviathanKeymapSummary[] Array of keymap summaries with conflict status.
function leviathan.keymap.list() end

---Create or fetch an autocmd group handle. Pass `{ clear = true }` to remove any prior autocmds in the group before returning the handle.
---@param name string Group name; the same string maps to the same handle for the lifetime of the plugin generation.
---@param opts LeviathanAutocmdGroupOpts Group creation options.
---@return integer Stable group handle to pass into `leviathan.autocmd.create`.
function leviathan.autocmd.group(name, opts) end

---Register an autocmd for a single typed event.
---@param event string|string[] Canonical event name, alias, or array of names.
---@param opts LeviathanAutocmdOpts Autocmd options including the callback.
function leviathan.autocmd.create(event, opts) end

---Remove every autocmd registered against a group handle.
---@param group integer Group handle returned by `leviathan.autocmd.group`.
function leviathan.autocmd.clear(group) end

---Register an overlay widget the host renders above the active screen.
---@param spec LeviathanOverlaySpec Overlay descriptor (id, widget, dismissible, priority, key_events).
function leviathan.ui.overlay(spec) end

---Compatibility callable alias for `leviathan.ui.dialog.open`; opens a repository-owned toolbar dialog on the active repository screen.
---@param spec LeviathanDialogSpec Repository toolbar dialog descriptor (id, text, optional controls, buttons).
function leviathan.ui.dialog(spec) end

---Open a repository-owned toolbar dialog on the active repository screen; button keys, including Escape, are data-driven.
---@param spec LeviathanDialogSpec Repository toolbar dialog descriptor (id, text, optional controls, buttons).
function leviathan.ui.dialog.open(spec) end

---Focus a text input control in the active repository toolbar dialog.
---@param dialog_id string Active toolbar dialog id.
---@param control_id string Dialog control id to focus.
---@return boolean|nil True on success, nil on failure.
---@return string|nil Error message on failure.
function leviathan.ui.dialog.focus_control(dialog_id, control_id) end

---Press a button in the active repository toolbar dialog.
---@param dialog_id string Active toolbar dialog id.
---@param button_id string Dialog button id to press.
---@return boolean|nil True on success, nil on failure.
---@return string|nil Error message on failure.
function leviathan.ui.dialog.press_button(dialog_id, button_id) end

---Remove an overlay owned by the calling plugin.
---@param id string Overlay id to remove.
function leviathan.ui.remove_overlay(id) end

---Contribute to a typed UI extension point and return a ledger-backed handle.
---@param point_id string Extension point id such as `repository.diff.context_menu`.
---@param spec LeviathanContributionSpec Contribution spec for the selected point.
---@return LeviathanContributionHandle|nil Contribution handle on success, nil on failure.
---@return string|nil Error message on failure.
function leviathan.ui.contribute(point_id, spec) end

---Contribute a context-menu item at an extension point.
---@param region string Extension point address (e.g. "repository.diff.context_menu").
---@param item LeviathanContextMenuItem Menu item (id, label, command, priority, condition_capability).
function leviathan.ui.context_menu(region, item) end

---Attach a decoration to a commit row (badge / icon / marker / lane).
---@param commit LeviathanCommit Commit row the decoration applies to.
---@param decoration LeviathanGraphDecoration Decoration AST: badge / icon / marker / lane.
function leviathan.ui.graph_decoration(commit, decoration) end

---Attach a decoration to a diff line / hunk (line_hint / hunk_badge / line_gutter).
---@param decoration LeviathanDiffDecoration Decoration AST: line_hint / hunk_badge / line_gutter.
function leviathan.ui.diff_decoration(decoration) end

---Register a plugin screen with init/view/update lifecycle callbacks.
---@param spec LeviathanScreenSpec Screen descriptor.
function leviathan.ui.screen.register(spec) end

---Add a slot and return a ledger-backed handle.
---@param spec LeviathanSlotSpec Slot spec including region, section/pane, id, priority, and widget.
---@return LeviathanSlotHandle|nil Slot handle on success, nil on failure.
---@return string|nil Error message on failure.
function leviathan.ui.slot.add(spec) end

---Remove a slot by full address.
---@param target LeviathanSlotTarget Slot address including region, section/pane, and id.
---@return boolean|nil True on success, nil on failure.
---@return string|nil Error message on failure.
function leviathan.ui.slot.remove(target) end

---Replace a slot by full address and return a handle.
---@param target LeviathanSlotTarget Existing slot address including region and id.
---@param spec LeviathanSlotSpec Replacement slot spec.
---@return LeviathanSlotHandle|nil Slot handle on success, nil on failure.
---@return string|nil Error message on failure.
function leviathan.ui.slot.replace(target, spec) end

---List mounted UI regions.
---@return string[] Region names in descriptor order.
---@return string|nil Error message on failure.
function leviathan.ui.region.list() end

---Describe one mounted UI region.
---@param name string Region name.
---@return table|nil Region descriptor on success, nil on failure.
---@return string|nil Error message on failure.
function leviathan.ui.region.describe(name) end

---Return the current typed UI context.
---@return LeviathanUiContext|nil Typed current UI context.
---@return string|nil Error message on failure.
function leviathan.ui.context.current() end

---Register a persistent dock panel with host-owned layout state.
