---Return the cached `leviathan.repository` snapshot table for the active repo.
---@return table Active repository snapshot.
function leviathan.repository.current() end

---Return the active repository's typed refs (locals, remotes, tags). Returns (refs, nil) or (nil, err).
---@return table|nil Refs snapshot on success.
---@return string|nil Error message on failure.
function leviathan.repository.refs() end

---Return the active repository's HEAD info: { hash, ref, detached }.
---@return table|nil HEAD snapshot on success.
---@return string|nil Error message on failure.
function leviathan.repository.head() end

---Return the working-tree status: { staged[], unstaged[], conflicted[] }.
---@return table|nil Status snapshot on success.
---@return string|nil Error message on failure.
function leviathan.repository.status() end

---Return up to `limit` commits from the active repository as `LeviathanCommit` rows.
---@param opts table Options table: { limit = 100, rev = "HEAD" }.
---@return LeviathanCommit[]|nil Commit list on success.
---@return string|nil Error message on failure.
function leviathan.repository.commits(opts) end

---Return per-file diff for `commit`. The result carries `commit` as `LeviathanCommit`.
---@param opts table Options table: { commit = LeviathanCommit }.
---@return LeviathanCommitDiff|nil Diff snapshot on success.
---@return string|nil Error message on failure.
function leviathan.repository.diff(opts) end

---Return the file at a given commit/path. The result carries `commit` as `LeviathanCommit`.
---@param opts table Options table: { commit = LeviathanCommit, path = "src/main.rs" }.
---@return LeviathanCommitFile|nil File-at-commit snapshot on success.
---@return string|nil Error message on failure.
function leviathan.repository.file_at(opts) end

---Blame is not yet wired through the host gateway. Returns (nil, "unsupported").
---@param opts table Options table: { path = "src/main.rs", line_range = {start,end} }.
---@return nil Always nil.
---@return string Error message.
function leviathan.repository.blame(opts) end

---Check out `ref`. Returns (true, nil) on enqueue + success, (false, err) otherwise.
---@param opts table { ref = "main" }
---@return boolean True on success, false on failure.
---@return string|nil Error message on failure.
function leviathan.git.checkout(opts) end

---Create branch `name` at `start_point` (defaults to HEAD).
---@param opts table { name = "topic", start_point = "HEAD" }
---@return boolean True on success, false on failure.
---@return string|nil Error message on failure.
function leviathan.git.create_branch(opts) end

---Delete branch `name`. `force = true` requires destructive confirmation.
---@param opts table { name = "topic", force = false }
---@return boolean True on success, false on failure.
---@return string|nil Error message on failure.
function leviathan.git.delete_branch(opts) end

---Create lightweight tag `name` at `target` (defaults to HEAD).
---@param opts table { name = "v1.2.3", target = "HEAD" }
---@return boolean True on success, false on failure.
---@return string|nil Error message on failure.
function leviathan.git.create_tag(opts) end

---Delete tag `name` locally. Destructive — requires confirmation.
---@param opts table { name = "v1.2.3" }
---@return boolean True on success, false on failure.
---@return string|nil Error message on failure.
function leviathan.git.delete_tag(opts) end

---Commit currently-staged changes with `message`.
---@param opts table { message = "..." }
---@return boolean True on success, false on failure.
---@return string|nil Error message on failure.
function leviathan.git.commit(opts) end

---Stash current dirty changes.
---@param opts table { message = "from plugin" }
---@return boolean True on success, false on failure.
---@return string|nil Error message on failure.
function leviathan.git.stash_push(opts) end

---Pop the most recent stash entry (or the entry at `index`).
---@param opts table { index = 0 }
---@return boolean True on success, false on failure.
---@return string|nil Error message on failure.
function leviathan.git.stash_pop(opts) end

---Reset current branch to `ref` with `mode` (soft|mixed|hard). `hard` requires destructive confirmation.
---@param opts table { ref = "HEAD~1", mode = "soft|mixed|hard" }
---@return boolean True on success, false on failure.
---@return string|nil Error message on failure.
function leviathan.git.reset(opts) end

---Fetch from `remote` (or every remote when omitted).
---@param opts table { remote = "origin" }
---@return boolean True on success, false on failure.
---@return string|nil Error message on failure.
function leviathan.git.fetch(opts) end

---Push the current branch to `remote`. Force pushes are not yet supported.
---@param opts table { remote = "origin", ref = "main" }
---@return boolean True on success, false on failure.
---@return string|nil Error message on failure.
function leviathan.git.push(opts) end

---Merge `ref` into the current branch. Destructive — requires confirmation.
---@param opts table { ref = "topic" }
---@return boolean True on success, false on failure.
---@return string|nil Error message on failure.
function leviathan.git.merge(opts) end

---Rebase the current branch onto `ref`. Destructive — requires confirmation.
---@param opts table { ref = "main" }
---@return boolean True on success, false on failure.
---@return string|nil Error message on failure.
function leviathan.git.rebase(opts) end

